class RsiReversion(Strategy):
    name = "rsi_reversion"
    LOOKBACK = 14
    HIGH = 70
    LOW = 30
    warmup_bars = 20

    def on_bar(self, symbol, store):
        window = store.window(symbol, self.timeframe)
        if len(window) < self.warmup_bars:
            return math.nan
        closes = window.closes()
        if len(closes) < self.LOOKBACK + 1:
            return math.nan
        diff = np.diff(closes)
        gains = np.where(diff > 0, diff, 0.0)
        losses = np.where(diff < 0, -diff, 0.0)
        avg_gain = ta.sma(gains, self.LOOKBACK)
        avg_loss = ta.sma(losses, self.LOOKBACK)
        if not math.isfinite(avg_gain) or not math.isfinite(avg_loss):
            return math.nan
        if avg_loss == 0.0:
            rsi = 100.0
        else:
            rs = avg_gain / avg_loss
            rsi = 100.0 - 100.0 / (1.0 + rs)
        rsi_last = rsi[-1]
        if not math.isfinite(rsi_last):
            return math.nan
        if rsi_last > self.HIGH:
            return -1.0
        if rsi_last < self.LOW:
            return 1.0
        return 0.0
